56	                        return false;
57	                    }
58	                    if (r > t0) {
59	                        t0 = r;
60	                    }
61	                } else {
62	                    if (r < t0) {
63	                        return false;
64	                    }
65	                    if (r < t1) {
66	                        t1 = r;
67	                    }
68	                }
69	            }
70	        }
