37	/**
38	 * 禁飞区审查业务的 H2 数据库测试（MODE=MySQL）。
39	 * 覆盖主流程、失败分支、版本失效（STALE）、幂等边界与真实并发互斥。
40	 */
41	@SpringBootTest
42	class AirspaceReviewServiceH2Test {
43	
44	    @Autowired
45	    private com.example.starter.service.AirspaceReviewService service;
46	    @Autowired
47	    private JdbcTemplate jdbc;
48	    @Autowired
49	    private ObjectMapper objectMapper;
50	
51	    private final AtomicInteger seq = new AtomicInteger();
52	
53	    @BeforeEach
54	    void cleanBefore() {
55	        cleanup();
56	    }
57	
58	    @AfterEach
59	    void cleanAfter() {
60	        cleanup();
61	    }
62	
63	    private void cleanup() {
64	        jdbc.update("DELETE FROM review");
65	        jdbc.update("DELETE FROM request_dedup");
66	        jdbc.update("DELETE FROM route_point");
67	        jdbc.update("DELETE FROM route");
68	        jdbc.update("DELETE FROM no_fly_zone");
69	        jdbc.update("UPDATE airspace_meta SET global_version = 0 WHERE id = 1");
70	    }
71	
72	    private String rid(String prefix) {
73	        return prefix + "-" + seq.incrementAndGet();
74	    }
75	
76	    private static List<RoutePointDto> pts(int... xy) {
77	        return java.util.stream.IntStream.range(0, xy.length / 2)
78	                .mapToObj(i -> new RoutePointDto(xy[2 * i], xy[2 * i + 1]))
79	                .toList();
80	    }
81	
82	    private ZoneCreateRequest zoneReq(String zoneId, int xMin, int yMin, int xMax, int yMax) {
83	        return new ZoneCreateRequest(zoneId, xMin, yMin, xMax, yMax, "req-" + rid("zone"));
84	    }
85	
86	    private ReviewResultDto dataOf(MutationResponse resp) {
87	        return objectMapper.convertValue(resp.data(), ReviewResultDto.class);
88	    }
89	
90	    // ============================ 主流程 ============================
91	
92	    @Test
93	    void clearThenBlockedThenClearAfterRevoke() {
94	        // 航线水平穿过 y=10
95	        MutationResponse route = service.createRoute(
96	                new RouteCreateRequest("r1", pts(0, 10, 100, 10), "req-" + rid("route")));
97	        assertFalse(route.replayed());
98	        assertEquals(1, objectMapper.convertValue(route.data(), Map.class).get("version"));
99	
100	        // 初始空域版本 0，无禁飞区 → CLEAR
101	        MutationResponse r1 = service.review(
102	                new ReviewRequest("r1", 1, 0L, "req-" + rid("review")));
103	        ReviewResultDto c1 = dataOf(r1);
104	        assertEquals("CLEAR", c1.conclusion());
105	        assertTrue(c1.hitZoneIds().isEmpty());
106	        assertEquals(0L, c1.airspaceVersion());
107	        assertTrue(c1.current());
108	
109	        // 创建与航线相交的禁飞区后，空域版本变为 1
110	        MutationResponse z1 = service.createZone(zoneReq("z1", 40, 5, 60, 15));
111	        assertEquals(1, ((Number) objectMapper.convertValue(z1.data(), Map.class)
112	                .get("airspaceVersion")).intValue());
113	
114	        // 用旧空域版本审核 → 409
115	        ApiException oldVersion = assertThrows(ApiException.class, () -> service.review(
116	                new ReviewRequest("r1", 1, 0L, "req-" + rid("review"))));
117	        assertEquals(HttpStatus.CONFLICT, oldVersion.status());
118	
119	        // 用新版本审核 → BLOCKED
120	        MutationResponse r2 = service.review(
121	                new ReviewRequest("r1", 1, 1L, "req-" + rid("review")));
122	        ReviewResultDto b1 = dataOf(r2);
123	        assertEquals("BLOCKED", b1.conclusion());
124	        assertEquals(List.of("z1"), b1.hitZoneIds());
125	
126	        // 撤销禁飞区，空域版本变为 2，再审核 → CLEAR
127	        service.revokeZone(new ZoneRevokeRequest("z1", "req-" + rid("revoke")));
128	        MutationResponse r3 = service.review(
129	                new ReviewRequest("r1", 1, 2L, "req-" + rid("review")));
130	        assertEquals("CLEAR", dataOf(r3).conclusion());
131	
132	        // 历史记录保留原结论
133	        assertEquals("BLOCKED", service.getReview(b1.reviewId()).conclusion());
134	        assertNull(service.getReview(b1.reviewId()).current());
135	    }
136	
137	    @Test
138	    void blockedReturnsAllHitZoneIdsSortedAndDeduplicated() {
139	        service.createRoute(
140	                new RouteCreateRequest("r2", pts(0, 10, 100, 10), "req-" + rid("route")));
141	        // 三个相交区域 + 一个不相交区域，id 故意乱序
142	        service.createZone(zoneReq("zeta", 40, 5, 60, 15));
143	        service.createZone(zoneReq("alpha", 45, 8, 55, 12));
144	        service.createZone(zoneReq("mid", 48, 9, 52, 11));
145	        service.createZone(zoneReq("faraway", -50, -50, -40, -40));
146	
147	        MutationResponse resp = service.review(
148	                new ReviewRequest("r2", 1, 4L, "req-" + rid("review")));
149	        assertEquals(List.of("alpha", "mid", "zeta"), dataOf(resp).hitZoneIds());
150	    }
151	
152	    @Test
153	    void crossingSegmentWithEndpointsOutsideIsBlocked() {
154	        service.createRoute(
155	                new RouteCreateRequest("r3", pts(0, 0, 100, 20), "req-" + rid("route")));
156	        service.createZone(zoneReq("box", 40, 5, 60, 15));
157	        MutationResponse resp = service.review(
158	                new ReviewRequest("r3", 1, 1L, "req-" + rid("review")));
159	        assertEquals("BLOCKED", dataOf(resp).conclusion());
160	        assertEquals(List.of("box"), dataOf(resp).hitZoneIds());
161	    }
162	
163	    @Test
164	    void boundaryTouchIsBlocked() {
165	        // 航段恰与区域底边接触
166	        service.createRoute(
167	                new RouteCreateRequest("r4", pts(0, 5, 100, 5), "req-" + rid("route")));
168	        service.createZone(zoneReq("edge", 40, 5, 60, 15));
169	        MutationResponse resp = service.review(
170	                new ReviewRequest("r4", 1, 1L, "req-" + rid("review")));
171	        assertEquals("BLOCKED", dataOf(resp).conclusion());
172	    }
173	
174	    // ============================ 失败分支 ============================
175	
176	    @Test
177	    void degenerateRectangleRejected() {
178	        ApiException ex = assertThrows(ApiException.class, () -> service.createZone(
179	                new ZoneCreateRequest("bad", 10, 10, 10, 20, "req-" + rid("zone"))));
180	        assertEquals(HttpStatus.BAD_REQUEST, ex.status());
181	    }
182	
183	    @Test
184	    void duplicateZoneRejected() {
185	        service.createZone(zoneReq("dup", 0, 0, 10, 10));
186	        ApiException ex = assertThrows(ApiException.class, () -> service.createZone(
187	                zoneReq("dup", 1, 1, 11, 11)));
188	        assertEquals(HttpStatus.CONFLICT, ex.status());
189	    }
190	
191	    @Test
192	    void revokeMissingOrTwiceRejected() {
193	        ApiException missing = assertThrows(ApiException.class, () -> service.revokeZone(
194	                new ZoneRevokeRequest("ghost", "req-" + rid("revoke"))));
195	        assertEquals(HttpStatus.NOT_FOUND, missing.status());
196	
197	        service.createZone(zoneReq("once", 0, 0, 10, 10));
198	        service.revokeZone(new ZoneRevokeRequest("once", "req-" + rid("revoke")));
199	        ApiException twice = assertThrows(ApiException.class, () -> service.revokeZone(
200	                new ZoneRevokeRequest("once", "req-" + rid("revoke2"))));
201	        assertEquals(HttpStatus.CONFLICT, twice.status());
202	    }
203	
204	    @Test
205	    void identicalPointsRejected() {
206	        ApiException ex = assertThrows(ApiException.class, () -> service.createRoute(
207	                new RouteCreateRequest("same", pts(5, 5, 5, 5), "req-" + rid("route"))));
208	        assertEquals(HttpStatus.BAD_REQUEST, ex.status());
209	    }
210	
211	    @Test
212	    void repeatedButNotAllIdenticalPointsAllowedAndZeroLengthSegmentHandled() {
213	        // 中间重复点合法（至少两个点不同）；零长度线段的几何判定也必须正确
214	        service.createRoute(new RouteCreateRequest("dup",
215	                pts(0, 10, 0, 10, 100, 10), "req-" + rid("route")));
216	        service.createZone(zoneReq("zz", 40, 5, 60, 15));
217	        MutationResponse resp = service.review(
218	                new ReviewRequest("dup", 1, 1L, "req-" + rid("review")));
219	        assertEquals("BLOCKED", dataOf(resp).conclusion());
220	        assertEquals(3, dataOf(resp).pointsSnapshot().size());
221	    }
222	
223	    @Test
224	    void replayedReviewKeepsOriginalConclusionAfterAirspaceChanges() {
225	        service.createRoute(
226	                new RouteCreateRequest("hr", pts(0, 10, 100, 10), "req-" + rid("route")));
227	        String requestId = "replay-after-change";
228	        MutationResponse first = service.review(
229	                new ReviewRequest("hr", 1, 0L, requestId));
230	        assertEquals("CLEAR", dataOf(first).conclusion());
231	        // 环境发生变化（建区）后，同键重放仍返回首次的不可变原结论
232	        service.createZone(zoneReq("hz", 40, 5, 60, 15));
233	        MutationResponse replay = service.review(
234	                new ReviewRequest("hr", 1, 0L, requestId));
235	        assertTrue(replay.replayed());
236	        ReviewResultDto dto = dataOf(replay);
237	        assertEquals("CLEAR", dto.conclusion());
238	        assertEquals(0L, dto.airspaceVersion());
239	        assertEquals(dataOf(first).reviewId(), dto.reviewId());
240	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM review", Integer.class));
241	    }
242	
243	    @Test
244	    void reviewMissingRouteIs404AndWrongVersionsAre409() {
245	        ApiException noRoute = assertThrows(ApiException.class, () -> service.review(
246	                new ReviewRequest("ghost", 1, 0L, "req-" + rid("review"))));
247	        assertEquals(HttpStatus.NOT_FOUND, noRoute.status());
248	
249	        service.createRoute(
250	                new RouteCreateRequest("rv", pts(0, 0, 10, 10), "req-" + rid("route")));
251	        ApiException badRouteVersion = assertThrows(ApiException.class, () -> service.review(
252	                new ReviewRequest("rv", 9, 0L, "req-" + rid("review"))));
253	        assertEquals(HttpStatus.CONFLICT, badRouteVersion.status());
254	
255	        service.createZone(zoneReq("z", 0, 0, 100, 100));
256	        ApiException badAirspaceVersion = assertThrows(ApiException.class, () -> service.review(
257	                new ReviewRequest("rv", 1, 0L, "req-" + rid("review"))));
258	        assertEquals(HttpStatus.CONFLICT, badAirspaceVersion.status());
259	    }
260	
261	    @Test
262	    void replaceRouteRejectsWrongExpectedVersionAndAdvancesVersion() {
263	        service.createRoute(
264	                new RouteCreateRequest("rp", pts(0, 0, 10, 10), "req-" + rid("route")));
265	        ApiException wrong = assertThrows(ApiException.class, () -> service.replaceRoute(
266	                new RouteReplaceRequest("rp", 7, pts(1, 1, 2, 2), "req-" + rid("replace"))));
267	        assertEquals(HttpStatus.CONFLICT, wrong.status());
268	
269	        ApiException missing = assertThrows(ApiException.class, () -> service.replaceRoute(
270	                new RouteReplaceRequest("ghost", 1, pts(1, 1, 2, 2), "req-" + rid("replace"))));
271	        assertEquals(HttpStatus.NOT_FOUND, missing.status());
272	
273	        MutationResponse ok = service.replaceRoute(
274	                new RouteReplaceRequest("rp", 1, pts(0, 0, 100, 100), "req-" + rid("replace")));
275	        assertEquals(2, objectMapper.convertValue(ok.data(), Map.class).get("version"));
276	        // 替换后旧航线版本审核 409
277	        ApiException stale = assertThrows(ApiException.class, () -> service.review(
278	                new ReviewRequest("rp", 1, 0L, "req-" + rid("review"))));
279	        assertEquals(HttpStatus.CONFLICT, stale.status());
280	        // 新版本可审核
281	        MutationResponse current = service.review(
282	                new ReviewRequest("rp", 2, 0L, "req-" + rid("review")));
283	        assertEquals("CLEAR", dataOf(current).conclusion());
284	    }
285	
286	    // ============================ STALE 语义 ============================
287	
288	    @Test
289	    void currentReviewBecomesStaleAfterZoneChangeAndRouteReplace() {
290	        service.createRoute(
291	                new RouteCreateRequest("st", pts(0, 10, 100, 10), "req-" + rid("route")));
292	        MutationResponse rev = service.review(
293	                new ReviewRequest("st", 1, 0L, "req-" + rid("review")));
294	        ReviewResultDto dto = dataOf(rev);
295	        assertEquals("CLEAR", dto.conclusion());
296	
297	        // 刚完成：当前结论可用
298	        ReviewResultDto current1 = service.getCurrentReview("st");
299	        assertEquals("CLEAR", current1.conclusion());
300	        assertTrue(current1.current());
301	
302	        // 空域变化：当前结论必须 STALE，旧 CLEAR 不能当成当前通过
303	        service.createZone(zoneReq("nz", -90, -90, -80, -80));
304	        ReviewResultDto stale1 = service.getCurrentReview("st");
305	        assertEquals("STALE", stale1.conclusion());
306	        assertFalse(stale1.current());
307	        // 历史结论不变
308	        assertEquals("CLEAR", service.getReview(dto.reviewId()).conclusion());
309	
310	        // 用新空域版本重新审核 → CLEAR，恢复可用
311	        MutationResponse rev2 = service.review(
312	                new ReviewRequest("st", 1, 1L, "req-" + rid("review")));
313	        assertTrue(dataOf(rev2).current());
314	        assertEquals("CLEAR", service.getCurrentReview("st").conclusion());
315	
316	        // 航线替换后再次 STALE
317	        service.replaceRoute(new RouteReplaceRequest(
318	                "st", 1, pts(0, 10, 100, 10), "req-" + rid("replace")));
319	        assertEquals("STALE", service.getCurrentReview("st").conclusion());
320	
321	        // 无审核记录查询 404
322	        ApiException ex = assertThrows(ApiException.class,
323	                () -> service.getCurrentReview("never-reviewed"));
324	        assertEquals(HttpStatus.NOT_FOUND, ex.status());
325	    }
326	
327	    @Test
328	    void blockedCurrentGoesStaleAndHistoricalBlockedStaysBlocked() {
329	        service.createRoute(
330	                new RouteCreateRequest("bs", pts(0, 10, 100, 10), "req-" + rid("route")));
331	        service.createZone(zoneReq("bz", 40, 5, 60, 15));
332	        MutationResponse rev = service.review(
333	                new ReviewRequest("bs", 1, 1L, "req-" + rid("review")));
334	        ReviewResultDto blocked = dataOf(rev);
335	        assertEquals("BLOCKED", blocked.conclusion());
336	        assertEquals("BLOCKED", service.getCurrentReview("bs").conclusion());
337	
338	        service.revokeZone(new ZoneRevokeRequest("bz", "req-" + rid("revoke")));
339	        // 撤销后旧 BLOCKED 对当前查询同样失效
340	        assertEquals("STALE", service.getCurrentReview("bs").conclusion());
341	        assertEquals("BLOCKED", service.getReview(blocked.reviewId()).conclusion());
342	    }
343	
344	    // ============================ 幂等 ============================
345	
346	    @Test
347	    void sameRequestReplaysOriginalResult() {
348	        String requestId = "fixed-replay-1";
349	        ZoneCreateRequest first = new ZoneCreateRequest("iz", 0, 0, 10, 10, requestId);
350	        MutationResponse r1 = service.createZone(first);
351	        assertFalse(r1.replayed());
352	
353	        // 同键同参重放：返回首次结果，不再次推进空域版本
354	        MutationResponse r2 = service.createZone(
355	                new ZoneCreateRequest("iz", 0, 0, 10, 10, requestId));
356	        assertTrue(r2.replayed());
357	        // JSON 重放后整数节点反序列化为 Integer，按数值比较
358	        assertEquals(1, ((Number) objectMapper.convertValue(r2.data(), Map.class)
359	                .get("airspaceVersion")).intValue());
360	        assertEquals(1L, jdbc.queryForObject(
361	                "SELECT global_version FROM airspace_meta WHERE id=1", Long.class));
362	        assertEquals(1, jdbc.queryForObject(
363	                "SELECT COUNT(*) FROM no_fly_zone", Integer.class));
364	    }
365	
366	    @Test
367	    void sameRequestWithDifferentParamsConflicts() {
368	        String requestId = "fixed-conflict-1";
369	        service.createZone(new ZoneCreateRequest("iz2", 0, 0, 10, 10, requestId));
370	        // 同键不同参数 → 409
371	        ApiException diffParams = assertThrows(ApiException.class, () -> service.createZone(
372	                new ZoneCreateRequest("iz2", 1, 1, 11, 11, requestId)));
373	        assertEquals(HttpStatus.CONFLICT, diffParams.status());
374	        // 同键用于不同类型操作 → 409
375	        ApiException diffKind = assertThrows(ApiException.class, () -> service.revokeZone(
376	                new ZoneRevokeRequest("iz2", requestId)));
377	        assertEquals(HttpStatus.CONFLICT, diffKind.status());
378	    }
379	
380	    @Test
381	    void failedRequestDoesNotConsumeIdempotencyKey() {
382	        String requestId = "fixed-fail-1";
383	        // 首次因非退化校验失败
384	        ApiException failed = assertThrows(ApiException.class, () -> service.createZone(
385	                new ZoneCreateRequest("fz", 5, 5, 5, 5, requestId)));
386	        assertEquals(HttpStatus.BAD_REQUEST, failed.status());
387	        // 失败回滚不占键
388	        assertNull(reviewDedupOrNull(requestId));
389	        // 键未被占用：同键可成功用于合法请求
390	        MutationResponse ok = service.createZone(
391	                new ZoneCreateRequest("fz", 0, 0, 10, 10, requestId));
392	        assertFalse(ok.replayed());
393	        // 成功后才占键
394	        assertNotNull(reviewDedupOrNull(requestId));
395	    }
396	
397	    @Test
398	    void reviewIdempotentReplayKeepsImmutableResult() {
399	        service.createRoute(
400	                new RouteCreateRequest("ir", pts(0, 10, 100, 10), "req-" + rid("route")));
401	        String requestId = "fixed-review-1";
402	        ReviewRequest req = new ReviewRequest("ir", 1, 0L, requestId);
403	        MutationResponse first = service.review(req);
404	        MutationResponse replay = service.review(
405	                new ReviewRequest("ir", 1, 0L, requestId));
406	        assertTrue(replay.replayed());
407	        assertEquals(dataOf(first).reviewId(), dataOf(replay).reviewId());
408	        assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM review", Integer.class));
409	    }
410	
411	    private Object reviewDedupOrNull(String requestId) {
412	        List<Map<String, Object>> rows = jdbc.queryForList(
413	                "SELECT request_id FROM request_dedup WHERE request_id = ?", requestId);
414	        return rows.isEmpty() ? null : rows.get(0);
415	    }
416	
417	    // ============================ 并发 ============================
418	
419	    @Test
420	    void concurrentZoneCreateAndReviewNeverMixesVersionsAndZones() throws Exception {
421	        int iterations = 12;
422	        ExecutorService pool = Executors.newFixedThreadPool(4);
423	        try {
424	            for (int i = 0; i < iterations; i++) {
425	                String routeId = "cr-" + i;
426	                String zoneId = "cz-" + i;
427	                // 每轮使用互不相交的 y 几何，避免历史轮次已提交区域命中本轮新航线
428	                int y = 10 + i * 100;
429	                service.createRoute(new RouteCreateRequest(
430	                        routeId, pts(0, y, 100, y), "req-" + rid("route")));
431	                long versionBefore = jdbc.queryForObject(
432	                        "SELECT global_version FROM airspace_meta WHERE id=1", Long.class);
433	
434	                CyclicBarrier barrier = new CyclicBarrier(2);
435	                // 审核方：明确提交建区前的空域版本
436	                Future<Object> reviewFuture = pool.submit(() -> {
437	                    barrier.await(5, TimeUnit.SECONDS);
438	                    try {
439	                        return service.review(new ReviewRequest(
440	                                routeId, 1, versionBefore, "req-review-" + routeId));
441	                    } catch (ApiException ex) {
442	                        return ex;
443	                    }
444	                });
445	                // 建区方：创建恰好封锁本轮航线的区域
446	                Future<Object> zoneFuture = pool.submit(() -> {
447	                    barrier.await(5, TimeUnit.SECONDS);
448	                    try {
449	                        return service.createZone(new ZoneCreateRequest(
450	                                zoneId, 40, y - 5, 60, y + 5, "req-zone-" + zoneId));
451	                    } catch (ApiException ex) {
452	                        return ex;
453	                    }
454	                });
455	
456	                Object reviewResult = reviewFuture.get(15, TimeUnit.SECONDS);
457	                Object zoneResult = zoneFuture.get(15, TimeUnit.SECONDS);
458	                assertTrue(zoneResult instanceof MutationResponse, "建区必须成功");
459	
460	                if (reviewResult instanceof MutationResponse mr) {
461	                    // 审核先拿锁：它看到的是建区前的一致快照，结论只能是 CLEAR，
462	                    // 绝不能出现“空域版本是旧的却命中新区域”的 BLOCKED
463	                    ReviewResultDto dto = dataOf(mr);
464	                    assertEquals("CLEAR", dto.conclusion(),
465	                            "并发审核携带旧空域版本时不得使用新建区域判定");
466	                    assertEquals(versionBefore, dto.airspaceVersion());
467	                } else {
468	                    // 建区先提交：版本已推进，审核必须 409，不能产生任何结论
469	                    ApiException ex = (ApiException) reviewResult;
470	                    assertEquals(HttpStatus.CONFLICT, ex.status());
471	                }
472	            }
473	        } finally {
474	            pool.shutdownNow();
475	        }
476	    }
