package com.example.starter.domain;

/**
 * 占用种类：常规占用与应急占用。
 * 应急占用只能由命中有效应急走廊的应急航线提出，且仍须通过禁飞审查。
 */
public enum OccupancyKind {
    /** 常规航线占用：走廊创建时可被要求让渡，命中有效走廊的新建申请返回 409。 */
    REGULAR,
    /** 应急航线占用：必须命中有效应急走廊，且引用的审查为应急 CLEAR。 */
    EMERGENCY
}

package com.example.starter.domain;

/**
 * 占用状态机。
 *
 * <p>ACTIVE（有效）→ YIELDED（被应急走廊让渡，不可自动恢复）；
 * ACTIVE → DEPARTED（已起飞，不可让渡）。YIELDED 航线只能重新审查并
 * 显式重新申请，新申请产生新的占用，原占用永久保留 YIELDED。</p>
 */
public enum OccupancyStatus {
    /** 有效占用：走廊创建时若时空相交，可让渡的被置为本态以外的 YIELDED。 */
    ACTIVE,
    /** 已让渡：走廊创建事务内固化，走廊撤销或到期均不自动恢复。 */
    YIELDED,
    /** 已起飞：走廊创建遇到该状态占用必须整次 422。 */
    DEPARTED
}

package com.example.starter.domain;

/**
 * 应急走廊状态：只能创建（ACTIVE）或撤销（REVOKED）。
 * 自然到期不写状态，有效性由 ACTIVE 状态与 UTC 时间窗共同判定。
 */
public enum CorridorStatus {
    /** 走廊已建立且未撤销；是否在有效期内另由时间窗判定。 */
    ACTIVE,
    /** 走廊已撤销，只影响后续占用，已让渡占用不恢复。 */
    REVOKED
}

package com.example.starter.domain;

/** 走廊不可变事件动作：建立与撤销。 */
public enum CorridorEventAction {
    /** 走廊建立（版本 1）。 */
    CREATED,
    /** 走廊撤销（沿用走廊版本，记录撤销时刻与原因）。 */
    REVOKED
}

package com.example.starter.domain;

/** 让渡航线重新申请的处置结果。 */
public enum ReapplyResult {
    /** 重新审查通过且新占用在一个事务内提交成功。 */
    APPROVED
}

