                        + "(corridor_id, x_min, y_min, x_max, y_max, start_ms, end_ms, alt_min, alt_max, "
                        + "priority, status, version, revoke_reason, revoked_ms, created_ms) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
