package com.example.starter.service;

import com.example.starter.api.ApiException;
import com.example.starter.api.dto.MutationResponse;
import com.example.starter.repo.DedupPo;
import com.example.starter.repo.ReviewRepository;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Clock;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.function.Supplier;

/**
 * 写操作幂等与事务执行器：所有业务变更与幂等去重记录在同一数据库事务内原子提交。
 *
 * <p>同键同参返回首次成功结果（标记 replayed=true）；同键异参/异种操作抛 409；
 * 业务异常回滚事务、不占用 requestId。</p>
 *
 * <p>同键并发时，落败事务可能先撞上唯一约束（DuplicateKeyException），
 * 也可能在持锁后读到赢家已提交状态而抛业务冲突（409/422）；落败者在回滚后
 * 用新事务查询去重表：赢家同键同参已提交则重放原结果，否则按原错误抛出。</p>
 */
@Component
public class IdempotentExecutor {

    private final ReviewRepository reviewRepo;
    private final ObjectMapper objectMapper;
    private final Clock clock;
    private final TransactionTemplate txTemplate;

    public IdempotentExecutor(ReviewRepository reviewRepo,
                              ObjectMapper objectMapper,
                              Clock clock,
                              PlatformTransactionManager transactionManager) {
        this.reviewRepo = reviewRepo;
        this.objectMapper = objectMapper;
        this.clock = clock;
        this.txTemplate = new TransactionTemplate(transactionManager);
    }

    /**
     * 在事务内执行幂等写操作。
     *
     * @param requestId 写操作全局唯一请求标识
     * @param kind      请求类型（异种操作复用同键时 409）
     * @param params    原始请求参数，用于规范化哈希比对
